import React, { useState, useEffect, useCallback } from 'react';
import {
  onAuthStateChanged,
  signInAnonymously,
  signInWithCustomToken,
  signOut as firebaseSignOut
} from 'firebase/auth';
import { doc, getDoc, setDoc, Timestamp } from 'firebase/firestore';
import { auth, db } from './firebase';


function App() {
  const [currentPage, setCurrentPage] = useState('login');
  const [currentUser, setCurrentUser] = useState(null);
  const [userId, setUserId] = useState(null);
  const [isAuthReady, setIsAuthReady] = useState(false);
  const [initialSignInAttempted, setInitialSignInAttempted] = useState(false);
  const [theme, setTheme] = useState('light');
  const [currentOffer, setCurrentOffer] = useState(null);
  const [currentArticle, setCurrentArticle] = useState(null);

  useEffect(() => {
    if (!auth) {
      setIsAuthReady(true);
      setCurrentPage('login');
      return;
    }

    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        if (db) {
          const userDocRef = doc(db, `/artifacts/myesh-platform/users/${user.uid}/profile`, 'userData');
          try {
            const userDocSnap = await getDoc(userDocRef);
            if (userDocSnap.exists()) {
              setCurrentUser({ uid: user.uid, email: user.email, ...userDocSnap.data() });
            } else {
              const basicProfile = {
                email: user.email,
                name: user.displayName || 'User',
                role: user.isAnonymous ? 'anonymous' : 'farmer',
                createdAt: Timestamp.now(),
                preferredLanguage: 'en'
              };
              await setDoc(userDocRef, basicProfile, { merge: true });
              setCurrentUser({ uid: user.uid, ...basicProfile });
            }
          } catch (e) {
            setCurrentUser({ uid: user.uid, email: user.email, name: 'User', role: 'farmer' });
          }
        }
        setUserId(user.uid);
        if (currentPage === 'login' || currentPage === 'register') setCurrentPage('dashboard');
      } else {
        setCurrentUser(null);
        setUserId(null);
        setCurrentPage('login');
      }
      setIsAuthReady(true);
    });

    return () => unsubscribe();
  }, [currentPage]);

  useEffect(() => {
    if (isAuthReady && auth && !initialSignInAttempted) {
      setInitialSignInAttempted(true);
      if (!auth.currentUser) {
        const attemptSignIn = async () => {
          try {
            if (typeof __initial_auth_token !== 'undefined' && __initial_auth_token) {
              await signInWithCustomToken(auth, __initial_auth_token);
            } else {
              await signInAnonymously(auth);
            }
          } catch (error) {
            console.error("Sign-in failed:", error);
          }
        };
        attemptSignIn();
      }
    }
  }, [isAuthReady, auth, initialSignInAttempted]);

  const handleNavigation = useCallback((page, data = null) => {
    setCurrentPage(page);
    if (page === 'offerDetail') setCurrentOffer(data);
    if (page === 'articleDetail') setCurrentArticle(data);
  }, []);

  const toggleTheme = useCallback(() => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', theme === 'dark');
  }, [theme]);

  const commonPages = {
    dashboard: <DashboardPage onNavigate={handleNavigation} />,
    maps: <MapsPage />,
    priceData: <PriceDataPage />,
    newsAndInsights: <NewsAndInsightsPage onNavigate={handleNavigation} />,
    knowledgeHub: <KnowledgeHubPage onNavigate={handleNavigation} />,
    sourcingHub: <SourcingHubPage onNavigate={handleNavigation} />,
    support: <SupportPage user={currentUser} />,
    addOffer: <AddOfferPage onNavigate={handleNavigation} user={currentUser} />,
    offerDetail: <OfferDetailPage offer={currentOffer} onBack={() => handleNavigation('sourcingHub')} />,
    articleDetail: <ArticleDetailPage article={currentArticle} onBack={() => handleNavigation('knowledgeHub')} />,
    profile: <ProfilePage user={currentUser} onNavigate={handleNavigation} />
  };

  let contentToRender;
  if (!isAuthReady) {
    contentToRender = <LoadingSpinner message="Initializing MyESH Platform." />;
  } else if (!auth || !db) {
    contentToRender = <FirebaseInitErrorPage />;
  } else if (!currentUser) {
    contentToRender = currentPage === 'register'
      ? <RegisterPage onNavigate={handleNavigation} authInstance={auth} dbInstance={db} />
      : <LoginPage onNavigate={handleNavigation} authInstance={auth} />;
  } else {
    contentToRender = commonPages[currentPage] || <DashboardPage onNavigate={handleNavigation} />;
  }

  return (
    <div className={`min-h-screen flex flex-col font-sans ${theme === 'dark' ? 'bg-gray-900 text-gray-200' : 'bg-[#F9F9F9] text-[#1F1F1F]'}`}>
      {currentUser && (
        <Navbar
          user={currentUser}
          onNavigate={handleNavigation}
          onSignOut={firebaseSignOut}
          authInstance={auth}
          toggleTheme={toggleTheme}
          currentTheme={theme}
          userId={userId}
        />
      )}
      <main className="flex-grow">{contentToRender}</main>
      <Footer />
    </div>
  );
}

export default App;
